import {useCallback, useEffect, useState} from 'react'
import ReactIs from 'react-is'
import {styled} from 'styled-components'

import {ThemeColorAvatarColorKey} from '../../../theme/system/color/_system'
import {_getArrayProp} from '../../styles/helpers'
import {useTheme_v2} from '../../theme/useTheme'
import {AvatarPosition, AvatarSize, AvatarStatus} from '../../types/avatar'
import {ElementType, Props} from '../../types/component'
import {Label} from '../label/label'
import {avatarColorStyle, avatarRootStyle, responsiveAvatarSizeStyle} from './styles'

import {
  avatarArrow,
  avatarBgStroke,
  avatarImage,
  avatarInitials,
  avatarRoot,
  avatarStroke,
  avatarStrokes,
} from './avatar.css'

/**
 * @public
 */
export interface AvatarOwnProps {
  /** @beta */
  __unstable_hideInnerStroke?: boolean
  animateArrowFrom?: AvatarPosition
  arrowPosition?: AvatarPosition
  color?: ThemeColorAvatarColorKey
  initials?: string
  onImageLoadError?: (event: Error) => void
  size?: AvatarSize | AvatarSize[]
  src?: string
  /**
   * The status of the entity this Avatar represents.
   * @alpha
   */
  status?: AvatarStatus
  title?: string
}

/**
 * @public
 */
export type AvatarProps<E extends ElementType = 'div'> = Props<AvatarOwnProps, E>

const AvatarBase = styled.div.attrs({className: avatarRoot})(avatarRootStyle)

const StyledAvatar = styled(AvatarBase)<{$color: ThemeColorAvatarColorKey; $size: AvatarSize[]}>(
  responsiveAvatarSizeStyle,
  avatarColorStyle,
)

function AvatarComponent(
  props: AvatarOwnProps & {as?: ElementType} & Omit<React.HTMLProps<HTMLDivElement>, 'as'>,
) {
  const {
    __unstable_hideInnerStroke,
    as: asProp,
    color = 'gray',
    src,
    title,
    initials,
    onImageLoadError,
    arrowPosition: arrowPositionProp,
    animateArrowFrom,
    ref,
    status = 'online',
    size: sizeProp = 1,
    ...restProps
  } = props
  const {avatar} = useTheme_v2()
  const as = ReactIs.isValidElementType(asProp) ? asProp : 'div'
  const size = _getArrayProp(sizeProp)
  // The rendered size follows `--avatar-size` per breakpoint (see styles.ts);
  // the first step also gives the image its intrinsic dimensions
  const avatarSize = avatar.sizes[size[0]] || avatar.sizes[0]

  const [arrowPosition, setArrowPosition] = useState<AvatarPosition | undefined>(
    animateArrowFrom || arrowPositionProp || 'inside',
  )

  const [imageFailed, setImageFailed] = useState<boolean>(false)

  // Adjusted during render rather than in an effect, so no committed frame
  // shows the initials for an image that has not tried to load yet.
  // https://react.dev/learn/you-might-not-need-an-effect#adjusting-some-state-when-a-prop-changes
  const [prevSrc, setPrevSrc] = useState(src)

  if (prevSrc !== src) {
    setPrevSrc(src)
    if (src) setImageFailed(false)
  }

  useEffect(() => {
    if (arrowPosition === arrowPositionProp) return undefined

    // Start animation in the next frame
    const raf = requestAnimationFrame(() => setArrowPosition(arrowPositionProp))

    return () => cancelAnimationFrame(raf)
  }, [arrowPosition, arrowPositionProp])

  const handleImageError = useCallback(() => {
    setImageFailed(true)

    if (onImageLoadError) {
      onImageLoadError(new Error('Avatar: the image failed to load'))
    }
  }, [onImageLoadError])

  return (
    <StyledAvatar
      as={as}
      data-as={typeof as === 'string' ? as : undefined}
      data-ui="Avatar"
      {...restProps}
      $color={color}
      $size={size}
      aria-label={title}
      data-arrow-position={arrowPosition}
      data-status={status}
      ref={ref}
      title={title}
    >
      <div className={avatarArrow}>
        <svg width="11" height="7" viewBox="0 0 11 7" fill="none">
          <path
            d="M6.67948 1.50115L11 7L0 7L4.32052 1.50115C4.92109 0.736796 6.07891 0.736795 6.67948 1.50115Z"
            fill={color}
          />
        </svg>
      </div>

      {!imageFailed && src && (
        <>
          {/*
           * A native <img> lets React wait for the image inside a <ViewTransition>
           * or a Suspense reveal. An `onLoad` handler or `loading="lazy"` would
           * opt it out of that, so neither is set. `width`/`height` give the
           * browser (and React's image byte estimate) the size before it loads.
           */}
          <img
            alt=""
            className={avatarImage}
            draggable={false}
            height={avatarSize.size}
            onError={handleImageError}
            src={src}
            width={avatarSize.size}
          />

          {/*
           * The strokes straddle the circle's edge and the svg clips the outer
           * half, leaving 1px of avatar color and 1px of card color inside.
           */}
          <svg className={avatarStrokes} viewBox="0 0 2 2" fill="none">
            {!__unstable_hideInnerStroke && (
              <circle
                className={avatarBgStroke}
                cx="1"
                cy="1"
                r="1"
                vectorEffect="non-scaling-stroke"
              />
            )}

            <circle
              className={avatarStroke}
              cx="1"
              cy="1"
              r="1"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        </>
      )}

      {(imageFailed || !src) && initials && (
        <>
          <div className={avatarInitials}>
            <Label
              as="span"
              size={size.map((s) => {
                if (s === 1) return 1
                if (s === 2) return 3
                if (s === 3) return 5

                return 0
              })}
              weight="medium"
            >
              {initials}
            </Label>
          </div>
        </>
      )}
    </StyledAvatar>
  )
}

/**
 * Avatars are used to represent people and other agents (e.g. bots).
 *
 * @public
 */
// oxlint-disable-next-line no-unsafe-type-assertion
export const Avatar = AvatarComponent as unknown as <E extends ElementType = 'div'>(
  props: AvatarProps<E>,
) => React.JSX.Element
