import {clsx} from 'clsx/lite'
import {useEffect, useImperativeHandle, useRef} from 'react'
import {styled} from 'styled-components'

import {switchRepresentationStyles, switchThumbStyles, switchTrackStyles} from './styles'

import {switchInput, switchRepresentation, switchRoot, switchThumb, switchTrack} from './switch.css'

/**
 * @public
 */
export interface SwitchProps {
  indeterminate?: boolean
}

const Representation = styled.span.attrs({className: switchRepresentation})(
  switchRepresentationStyles,
)
const Track = styled.span.attrs({className: switchTrack})(switchTrackStyles)
const Thumb = styled.span.attrs({className: switchThumb})<{
  $checked?: boolean
  $indeterminate?: boolean
}>(switchThumbStyles)

/**
 * The `Switch` component allows the user to toggle a setting on and off.
 *
 * Extends all properties of an `<input type="checkbox" />` element, except type.
 *
 * @public
 */
export function Switch(
  props: Omit<React.HTMLProps<HTMLInputElement>, 'as' | 'type'> & SwitchProps,
) {
  const {
    checked,
    className,
    disabled,
    indeterminate,
    readOnly,
    ref: forwardedRef,
    style,
    ...restProps
  } = props
  const ref = useRef<HTMLInputElement | null>(null)

  useImperativeHandle<HTMLInputElement | null, HTMLInputElement | null>(
    forwardedRef,
    () => ref.current,
  )

  useEffect(() => {
    if (ref.current) {
      // Set the indeterminate state
      ref.current.indeterminate = indeterminate || false
    }
  }, [indeterminate])

  return (
    <span className={clsx(switchRoot, className)} data-ui="Switch" style={style}>
      <input
        className={switchInput}
        data-read-only={!disabled && readOnly ? '' : undefined}
        {...restProps}
        checked={indeterminate !== true && checked}
        disabled={disabled || readOnly}
        type="checkbox"
        ref={ref}
      />
      <Representation aria-hidden data-name="representation" data-ui="Switch__representation">
        <Track data-ui="Switch__track" />
        <Thumb $checked={checked} $indeterminate={indeterminate} data-ui="Switch__thumb" />
      </Representation>
    </span>
  )
}
